def build(help_names, shadow_with_host=False):
    @group(context_settings={"help_option_names": help_names})
    def cli():
        pass

    if shadow_with_host:
        @command("foo")
        @argument("required_arg")
        @option("--host", "-h", "host", default="localhost")
        def foo(required_arg, host):
            echo(f"required_arg={required_arg} host={host}")
    else:
        @command("foo")
        @argument("required_arg")
        def foo(required_arg):
            echo(f"required_arg={required_arg}")

    cli.add_command(foo)
    return cli


